import { base, ignorePatterns, react } from '@rhyek/oxc-config/oxlint';
import { defineConfig } from 'oxlint';

// One root config lints the whole tree. The rules, and why some are off, are in
// `synced-utils/oxc-config/src/oxlint.ts`; this file adds only what is this repo's own.
export default defineConfig({
  extends: [base, react],
  env: { node: true },
  ignorePatterns: [
    ...ignorePatterns,
    // Generated by kysely-codegen — never hand-edited.
    '**/lib/db/codegen.d.ts',
    // Vendored shadcn/ui CLI output — kept pristine so `shadcn diff`/`--overwrite` stay clean.
    // Behavior changes go in a wrapper under components/ui-kit/, never by editing these.
    'projects/web/src/components/ui/**',
    // Generated by @tanstack/router-plugin.
    'projects/web/src/routeTree.gen.ts',
  ],

  overrides: [
    {
      // The node:test specs named `.test.ts`: what the shared config allows a spec.
      files: ['**/*.test.ts'],
      rules: {
        'eslint/no-console': 'off',
        'typescript/no-explicit-any': 'off',
        'typescript/require-await': 'off',
      },
    },
    {
      // The seed scripts report what they wrote.
      files: ['projects/db/seed/**'],
      rules: { 'eslint/no-console': 'off' },
    },
    {
      // A label wrapping one of the shadcn controls labels it: they render the real control.
      files: ['projects/web/**'],
      rules: {
        'jsx-a11y/label-has-associated-control': [
          'error',
          { controlComponents: ['Checkbox', 'Switch', 'RadioGroupItem'] },
        ],
      },
    },
    {
      // No decorators here, so a type-only import can say so. The Nest apps (scrape-txs,
      // tx-payees) stay out: their injected constructor types must remain value imports, and
      // oxlint's version of the rule cannot tell those apart (see the shared config).
      files: ['projects/db/**', 'projects/web/**'],
      rules: {
        'typescript/consistent-type-imports': [
          'error',
          {
            prefer: 'type-imports',
            fixStyle: 'inline-type-imports',
            disallowTypeAnnotations: false,
          },
        ],
      },
    },
  ],
});
